const mapValid = $('Map Candidate Fields').all().filter((item) => !item.json.__skip);
const inputs = $input.all();
const candidates = mapValid.slice(-inputs.length);

return inputs.map((item, index) => {
  const llmOut = item.json;
  const candidate = candidates[index]?.json || {};

  const raw = String(llmOut.text || llmOut.output || '').trim();
  let match_score = 50;
  let match_insights = [];

  const start = raw.indexOf('{');
  const end = raw.lastIndexOf('}');
  if (start >= 0 && end > start) {
    try {
      const parsed = JSON.parse(raw.slice(start, end + 1));
      if (parsed.match_score != null && Number.isFinite(Number(parsed.match_score))) {
        match_score = Math.max(0, Math.min(100, Math.round(Number(parsed.match_score))));
      }
      if (Array.isArray(parsed.match_insights)) {
        match_insights = parsed.match_insights
          .filter((x) => x && typeof x === 'object')
          .map((x) => ({
            kind: ['positive', 'warning', 'neutral'].includes(String(x.kind)) ? String(x.kind) : 'neutral',
            text: String(x.text || x.message || '').trim(),
          }))
          .filter((x) => x.text);
      }
    } catch (e) {}
  }

  const { location_priority, __skip, ...rest } = candidate || {};

  return {
    json: {
      ...rest,
      match_score,
      ai_analysis: '',
      match_insights,
    },
  };
});

const webhook = $('Webhook').first().json.body || {};
const locationSearch = String(webhook.location || '').toLowerCase();
const isIraqSearch =
  locationSearch.includes('iraq') ||
  locationSearch.includes('baghdad') ||
  locationSearch.includes('عراق') ||
  locationSearch.includes('بغداد');

const US_EXCLUDE = [
  'united states', 'u.s.', 'usa', 'america', 'california', 'texas', 'new york', 'florida', 'orange county',
];
const NON_IRAQ_EXCLUDE = [
  'iran', 'tehran', 'turkey', 'uae', 'dubai', 'saudi', 'jordan', 'kuwait', 'qatar', 'egypt',
];

function norm(s) {
  return String(s || '').toLowerCase();
}

function isBadLocation(j) {
  const loc = norm(j.location);
  if (!loc) return false;
  if (US_EXCLUDE.some((t) => loc.includes(t))) return true;
  if (NON_IRAQ_EXCLUDE.some((t) => loc.includes(t)) && !loc.includes('iraq') && loc !== 'iq') return true;
  return false;
}

function rankScore(j) {
  let score = Number(j.match_score) || 0;
  if (Number(j.location_priority) === 1) score += 8;
  if (locationSearch.includes('baghdad') && norm(j.location).includes('baghdad')) score += 5;
  return score;
}

const items = $input.all().map((i) => i.json);
items.sort((a, b) => rankScore(b) - rankScore(a));

let pool = items.filter((j) => (Number(j.match_score) || 0) >= 50);
if (pool.length === 0) pool = items.filter((j) => (Number(j.match_score) || 0) >= 45);
if (pool.length === 0) pool = items.filter((j) => (Number(j.match_score) || 0) >= 40);
if (pool.length === 0) pool = items;

if (isIraqSearch) {
  const cleaned = pool.filter((j) => !isBadLocation(j));
  if (cleaned.length > 0) pool = cleaned;
}

pool.sort((a, b) => rankScore(b) - rankScore(a));

return pool.map((j) => {
  const { location_priority, __skip, ...rest } = j;
  return { json: rest };
});

const mapped = $input.all();
if (mapped.length === 0) {
  return [{ json: { __completeOnly: true } }];
}
return mapped;

const first = $input.first().json;
const primary = String(first.text || first.output || '').trim();
const webhook = $('Webhook').first().json.body || {};
const t = $('Apply Translation').first().json || {};
const position = String(t.position || webhook.position || '').trim();
const location = String(t.location || webhook.location || '').trim();
const posLower = position.toLowerCase();
const tier = $('Resolve Search Tier').first().json || {};
const maxVariants = Number(tier.queryVariants) || 2;

function buildLocFilter(loc) {
  const l = String(loc || '').trim();
  if (!l) return '("Iraq")';
  const city = l.split(',')[0].trim();
  const terms = [];
  if (city) terms.push('"' + city + '"');
  terms.push('"Iraq"');
  return '(' + terms.join(' OR ') + ')';
}
const iraqLoc = buildLocFilter(location);

// Role noun = LAST meaningful word (e.g. "External Auditor" -> "Auditor", not "External").
const roleWords = position.split(/\s+/).filter((w) => w.length > 3);
const roleNoun = roleWords.length ? roleWords[roleWords.length - 1] : (position.split(/\s+/)[0] || '');

const queries = [];
function add(q) {
  const s = String(q || '').trim();
  if (s && queries.indexOf(s) === -1) queries.push(s);
}

// Precision-first primary (from the LLM), then location-relaxed recall variants so a
// niche role in a small city still surfaces Iraq-wide matches. Always use the FULL
// title / role noun -- never a lone first word like "External", which used to fill the
// pool with unrelated profiles that the match gate then discarded.
add(primary);
if (position) add('site:linkedin.com/in/ "' + position + '" AND ' + iraqLoc);
if (roleNoun && roleNoun.toLowerCase() !== position.toLowerCase()) {
  add('site:linkedin.com/in/ "' + roleNoun + '" AND ' + iraqLoc);
}

if (maxVariants >= 3) {
  if (posLower.includes('compensation') || posLower.includes('benefits')) {
    add('site:linkedin.com/in/ ("Compensation" OR "Benefits" OR "Total Rewards" OR "C&B" OR "Payroll") AND ' + iraqLoc);
    add('site:linkedin.com/in/ ("Human Resources" OR "HR") ("Compensation" OR "Benefits" OR "Payroll") AND ' + iraqLoc);
  } else if (posLower.includes('audit')) {
    add('site:linkedin.com/in/ ("Auditor" OR "Audit" OR "Internal Auditor" OR "External Auditor") AND ' + iraqLoc);
    add('site:linkedin.com/in/ ("Accountant" OR "Finance" OR "CPA" OR "ACCA") AND ' + iraqLoc);
  } else if (posLower.includes('hr') || posLower.includes('human resources')) {
    add('site:linkedin.com/in/ "Human Resources" AND ' + iraqLoc);
  } else {
    const chunks = position.split(/\s+/).filter((w) => w.length > 3).slice(0, 3);
    if (chunks.length) {
      add('site:linkedin.com/in/ (' + chunks.map((w) => '"' + w + '"').join(' OR ') + ') AND ' + iraqLoc);
    }
  }
}

return queries.slice(0, maxVariants).map((q) => ({ json: { q } }));

const webhook = $('Webhook').first().json.body || {};
const searchId = String(webhook.searchId || 'default');
const sd = $getWorkflowStaticData('global');
if (!sd.hhStats) sd.hhStats = {};
sd.hhStats[searchId] = { enrichOk: 0, enrichErr: 0 };
if (!sd.hhCandidates) sd.hhCandidates = {};
sd.hhCandidates[searchId] = [];

const raw = Number(webhook.minCandidateCount) || 20;
const minCount = raw >= 40 || raw === 30 ? 40 : 20;
const isFull = minCount >= 40;

// Skip the translation LLM when the inputs are already English (ASCII only). A
// non-ASCII char (Arabic) means translation is still needed. This keeps a transient
// OpenAI failure on the translate step from aborting an English search.
const needsTranslation = /[^�-]/.test(
  String(webhook.position || '') + ' ' + String(webhook.location || ''),
);

return [
  {
    json: {
      minCount,
      queryVariants: isFull ? 4 : 2,
      pagesPerQuery: isFull ? 5 : 2,
      maxEnrich: isFull ? 55 : 35,
      streamBatchSize: 20,
      needsTranslation,
    },
  },
];

const wh = $('Webhook').first().json.body || {};
const searchId = String(wh.searchId || '');
const sd = $getWorkflowStaticData('global');
const phase2Active =
  Boolean(sd.hhExpansionActive?.[searchId]) || Boolean(sd.hhPhase2?.[searchId]);

return { json: { batchDone: true, itemIndex: $itemIndex, __phase2: phase2Active } };

const wh = $('Webhook').first().json.body || {};
const searchId = String(wh.searchId || '');
const input = $input.first().json || {};

if (input.__completeOnly) {
  const body = { searchId, searchComplete: true };
